    # Locate non-background horizontal runs touching the top and bottom edges.
    def edge_run(r):
        runs = []
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color = grid[r][c]
            start = c
            while c < w and grid[r][c] == color:
                c += 1
            runs.append((start, c, color))
        return runs

    top_runs = edge_run(0)
    bottom_runs = edge_run(h - 1)
